// src/App.tsx
import { useState } from 'react';
export default function App() {
const [count, setCount] = useState(0);
return (
<div>
<h1>Count: {count}</h1>
<button onClick={() => setCount(c => c + 1)}>+1</button>
<ChildList items={['a', 'b', 'c']} />
</div>
);
}
function ChildList({ items }: { items: string[] }) {
return (
<ul>
{items.map((x, i) => <li key={i}>{x}</li>)}
</ul>
);
}
Rules of thumb:
JSX — HTML-like syntax that compiles to React.createElement(...).
useState for local state.
useEffect for side effects (data fetching, subscriptions).
Props are read-only inputs from parent.
Always give array children a stable key prop.
Component names are PascalCase.

import { useEffect, useState } from 'react';
export default function Users() {
const [users, setUsers] = useState([]);
useEffect(() => {
fetch('/api/users').then(r => r.json()).then(setUsers);
}, []); // empty deps → run once on mount
return <ul>{users.map(u => <li key={u.id}>{u.name}</li>)}</ul>;
}
